// Guards the ASCII animation style (DESIGN.md, "Animation style").
//
//   node .dsh/ascii-style-check.cjs
//
// Every ASCII scene changes whole character frames with steps(1, end). The art
// is never skewed, rotated, scaled or smoothly moved, and no script animates
// it. The frames are generated by .dsh/build-ascii.py; CI regenerates them and
// fails if the committed copy differs.
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');

const root = path.resolve(__dirname, '..');
const read = file => fs.readFileSync(path.join(root, file), 'utf8');
const failures = [];
const check = (ok, message) => { if (!ok) failures.push(message); };

const MOTION = /\b(transform|translate|rotate|scale|skew|matrix|perspective|offset-path|animation-timeline|scroll-timeline|view-timeline)\b/;
const sheets = ['css/ascii.css', 'css/ascii-frames.css'];

function keyframes(css) {
  const blocks = [];
  const re = /@keyframes\s+([\w-]+)\s*\{/g;
  let m;
  while ((m = re.exec(css))) {
    let depth = 1, i = re.lastIndex;
    while (depth && i < css.length) { if (css[i] === '{') depth++; else if (css[i] === '}') depth--; i++; }
    blocks.push({ name: m[1], body: css.slice(re.lastIndex, i - 1) });
  }
  return blocks;
}

for (const file of sheets) {
  const css = read(file);
  for (const { name, body } of keyframes(css)) {
    check(!MOTION.test(body), `${file}: @keyframes ${name} animates a transform or scroll timeline`);
    for (const [, value] of body.matchAll(/(?:^|[;{])\s*(?:left|top|right|bottom)\s*:\s*([^;}]+)/g)) {
      check(/^-?\d+(ch|em)$/.test(value.trim()), `${file}: @keyframes ${name} moves to ${value.trim()} — travelling marks jump whole ch/em cells`);
    }
  }
  for (const [, value] of css.matchAll(/animation(?:-timing-function)?\s*:\s*([^;}]+)/g)) {
    if (/^none\b/.test(value.trim())) continue;
    if (/\b(ease|linear|cubic-bezier|steps\((?!1\s*,\s*end\)))/.test(value) || (/animation\s*:/.test(value) && !/steps\(1\s*,\s*end\)/.test(value))) {
      check(/steps\(1\s*,\s*end\)/.test(value), `${file}: animation "${value.trim()}" must use steps(1, end)`);
    }
  }
}

// Any other stylesheet that touches an ASCII scene may not animate it.
for (const file of fs.readdirSync(path.join(root, 'css')).filter(f => f.endsWith('.css') && !sheets.includes('css/' + f))) {
  const css = read('css/' + file);
  for (const rule of css.matchAll(/([^{}]*\.(?:ascii|deck-ascii)[^{}]*)\{([^{}]*)\}/g)) {
    check(!/\banimation\b|\btransition\b|\btransform\b/.test(rule[2]), `css/${file}: "${rule[1].trim()}" animates an ASCII scene outside css/ascii*.css`);
  }
  for (const { name, body } of keyframes(css)) {
    check(!/^ascii/.test(name), `css/${file}: @keyframes ${name} belongs in the generator`);
    void body;
  }
}

// Runtime animation is HTML and CSS only.
for (const file of fs.readdirSync(path.join(root, 'js')).filter(f => f.endsWith('.js'))) {
  const js = read('js/' + file);
  check(!/ascii/i.test(js), `js/${file}: scripts must not reach into the ASCII scenes`);
  check(!/requestAnimationFrame|\.animate\(|new\s+Animation\(|KeyframeEffect/.test(js), `js/${file}: no JavaScript animation loops or Web Animations`);
}
for (const file of fs.readdirSync(path.join(root, '_includes/ascii'))) {
  const markup = read('_includes/ascii/' + file);
  check(!/<script|<canvas|\son\w+=/i.test(markup), `_includes/ascii/${file}: scenes are plain HTML`);
  check(!/style="[^"]*(transform|rotate|skew|scale)/.test(markup), `_includes/ascii/${file}: no inline transforms`);
}

// Every scene in ascii-frames.css must have a still first frame for reduced motion.
const frames = read('css/ascii-frames.css');
for (const [, selector, name] of frames.matchAll(/([^\n{}]+)\{content:"[^\n]*?";animation:([\w-]+) /g)) {
  check(frames.includes(`@keyframes ${name}{`), `${selector}: missing @keyframes ${name}`);
}
assert.match(read('css/ascii.css'), /prefers-reduced-motion: reduce[\s\S]*animation: none !important/);

if (failures.length) {
  console.error(failures.join('\n'));
  process.exit(1);
}
console.log('ASCII scenes: stepped character frames only, no transforms, no script animation.');
